Actionscript.script:
onClipEvent (enterFrame) {
	当前时长 +=1;
	if (当前时长 > 最大时长 || _parent._parent._name == _root.控制目标 && Key.isDown(_parent._parent.技能按键值) == true)
	{
		_parent.gotoAndPlay("天启大封印发射");
	}
}
onClipEvent (load) {
	当前时长 = 0;
	最大时长 = 12;
}

onClipEvent (load) {
	_parent._parent.skillShadow = this;
	if (!_root.是否阴影)
	{
		this._visible = false;
	}
	缩放乘数 = 3.611 * 175 / _parent._parent.身高;
	if (_parent.技能浮空 == true)
	{
		if (_parent._parent.浮空)
		{
			this._y = 233.05 + (_parent._parent.起始Y - _parent._parent._y - _parent._parent.垂直速度) * 缩放乘数;
		}
	}
}
onClipEvent (enterFrame) {
	if (_root.是否阴影 and _parent._parent.浮空)
	{
		this._y = 233.05 + (_parent._parent.起始Y - _parent._parent._y - _parent._parent.垂直速度) * 缩放乘数;
	}
	else
	{
		this._y = 233.05;
	}
}
